function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is between 1 and 10^5.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges needs exactly n - 1 edges.';
  const parent = Array.from({ length: n + 1 }, (_, i) => i);
  const find = x => {
    while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
  };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 1 || v < 1 || u > n || v > n) return 'Edge endpoints are between 1 and n.';
    const ru = find(u), rv = find(v);
    if (ru === rv) return 'The edges must form a tree (no cycles or repeated edges).';
    parent[ru] = rv;
  }
  return null;
}

