function countPaths(n, edges) {
  const isPrime = new Array(n + 1).fill(true);
  isPrime[0] = false;
  isPrime[1] = false;
  for (let p = 2; p * p <= n; p++) {
    if (!isPrime[p]) continue;
    for (let multiple = p * p; multiple <= n; multiple += p) {
      isPrime[multiple] = false;
    }
  }
  const graph = Array.from({ length: n + 1 }, () => []);
  for (const [u, v] of edges) {
    graph[u].push(v);
    graph[v].push(u);
  }
  const size = new Array(n + 1).fill(0);
  const fill = (start) => {
    const stack = [start];
    const component = [];
    size[start] = -1;
    while (stack.length > 0) {
      const node = stack.pop();
      component.push(node);
      for (const next of graph[node]) {
        if (!isPrime[next] && size[next] === 0) {
          size[next] = -1;
          stack.push(next);
        }
      }
    }
    for (const node of component) {
      size[node] = component.length;
    }
  };
  let total = 0;
  for (let prime = 2; prime <= n; prime++) {
    if (!isPrime[prime]) continue;
    let reached = 0;
    for (const next of graph[prime]) {
      if (isPrime[next]) continue;
      if (size[next] === 0) fill(next);
      total += size[next] * (reached + 1);
      reached += size[next];
    }
  }
  return total;
}

