function countPaths(n, edges) {
  const prime = x => {
    if (x < 2) return false;
    for (let d = 2; d * d <= x; d++) if (x % d === 0) return false;
    return true;
  };
  const adj = Array.from({ length: n + 1 }, () => []);
  for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
  let count = 0;
  // From every node a, walk the whole tree carrying the number of primes seen on the path so far.
  for (let a = 1; a <= n; a++) {
    const stack = [[a, 0, prime(a) ? 1 : 0]];
    while (stack.length) {
      const [node, parent, primes] = stack.pop();
      if (node > a && primes === 1) count++;
      for (const next of adj[node]) if (next !== parent) stack.push([next, node, primes + (prime(next) ? 1 : 0)]);
    }
  }
  return count;
}

