function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 12);
  const labels = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [labels[i], labels[j]] = [labels[j], labels[i]];
  }
  const shape = rand();
  const edges = [];
  for (let i = 1; i < n; i++) {
    let parent;
    if (shape < 0.2) parent = i - 1;
    else if (shape < 0.35) parent = 0;
    else if (shape < 0.5) parent = Math.max(0, i - 1 - Math.floor(rand() * 3));
    else parent = Math.floor(rand() * i);
    edges.push(rand() < 0.5 ? [labels[i], labels[parent]] : [labels[parent], labels[i]]);
  }
  return [n, edges];
}
